/* Twilight is revealed by the players, rather than an always-on particle overlay. */
let worldAwake=false,lastTrail=null,lastDuskScene=null;
const daylightScene=scene,daylightDefs=daylightScene().match(/<defs>([\s\S]*?)<\/defs>/)[1];
const duskPalette={'#8dada6':'#394c77','#a1c6c1':'#405f86','#d9eeea':'#a3dbea','#98ad94':'#353c67','#d8ceb5':'#626184','#b3b59b':'#8c88a7','#b6bba1':'#6a718c','#c4c5ac':'#73768f','#a8b197':'#818aa1','#d5d4bb':'#939bb0','#819c72':'#6d8e9a','#e9e0c8':'#77768f','#e2d8bf':'#6c6d86','#c9c3a8':'#9393a6','#f0e9d6':'#a3a7ba','#8caeaa':'#334266','#a1c5bf':'#405a85','#d5e9df':'#94cfe3','#c2b592':'#797393','#9a9e7b':'#b8a6bb','#edf2e6':'#444364','#a6b8a0':'#b8a6ce','#748b70':'#d3c1ec','#f5f0dc':'#4d4c70','#9ba98a':'#a795bc','#697f63':'#f0d6a6','#7f8d74':'#c9bcdf','#f0f1e9':'#6b6488','#b99b73':'#8d7194','#8e8063':'#705b80'};
function nightColors(s){return s.replace(/#[a-fA-F0-9]{6}/g,c=>duskPalette[c.toLowerCase()]||c)}
function diamond(x,y,s,fill='#f8e7b8'){return `<path d="M${x} ${y-s}q0 ${s} ${s} ${s}q-${s} 0-${s} ${s}q0-${s}-${s}-${s}q${s} 0 ${s}-${s}" fill="${fill}"/>`}
function starBridge(){return `<g id="coopBridge" class="star-bridge" opacity="1"><path d="M358 310Q475 289 594 310" fill="none" stroke="#9d92c8" stroke-width="1" opacity=".35"/><path class="bridge-thread" d="M358 310Q475 289 594 310" fill="none" stroke="url(#bridgeSpectrum)" stroke-width="4"/>${Array.from({length:15},(_,i)=>{const x=360+i*15.5,y=317-Math.sin(i/14*Math.PI)*9;return `<g class="star-tile" data-tile="${i}" transform="translate(${x} ${y})"><path d="M-6-13 7-15 7 12-6 14z" fill="#9e92ca" opacity=".14"/><g class="tile-blue"><path d="M-6-13 7-15 7 12-6 14z" fill="#b0d9ff" stroke="#e5e2ff" stroke-width=".7"/><path d="M-5-12 6-14" stroke="#fff9e1" stroke-width="2"/></g><g class="tile-gold"><path d="M-6-13 7-15 7 12-6 14z" fill="#f5d9ac" fill-opacity=".45" stroke="#ffe7bc" stroke-width="1"/><path d="M-5 11 6 9" stroke="#fff2cf" stroke-width="2"/></g>${diamond(0,-22,2.5,'#f9eac8')}</g>`}).join('')}<path class="bridge-reflected-thread" d="M358 333Q475 312 594 333" fill="none" stroke="url(#bridgeSpectrum)" stroke-width="3"/>${diamond(418,285,4)}${diamond(475,277,6)}${diamond(532,285,4)}<path class="bridge-rail" d="M356 286Q475 254 596 286" fill="none" stroke="#e9c7fb" stroke-width="1.5" stroke-dasharray="2 12"/></g>`}
house=function(){return `<g class="twilight-house" transform="translate(735 135)"><rect width="156" height="172" rx="7" fill="#77618c" stroke="#b19ac0" stroke-width="1"/><path d="M-22 3l100-78L178 3" fill="#534869"/><path d="M-13 0l90-65 91 65" fill="none" stroke="#b18ba8" stroke-width="4"/><path d="M11-8 78-59 147-8" fill="none" stroke="#7e657f" stroke-width="2"/><rect x="51" y="91" width="53" height="81" rx="26" fill="#393956" stroke="#b49eb5"/><rect class="house-window" x="15" y="34" width="34" height="38" rx="6" fill="#f0c98f"/><path d="M32 35v37m-17-19h34" stroke="#a78387" stroke-width="3"/><circle cx="94" cy="138" r="3" fill="#ebd49e"/><path d="M-17 173h192" stroke="#97879d" stroke-width="7"/><path d="M118-38v-29h15v40" fill="#726383"/><g class="window-halo"><ellipse cx="32" cy="53" rx="52" ry="48" fill="url(#warmPool)"/></g></g>`};
scene=function(extra='',people=''){
if(extra.includes('id="coopBridge"'))extra=extra.replace(/<g id="coopBridge"[^>]*>[\s\S]*?<\/g>/,starBridge());
const defs=daylightDefs.replace(/<linearGradient id="leafTone"[\s\S]*?<\/linearGradient>/,'<linearGradient id="leafTone" x2=".8" y2="1"><stop stop-color="#747493"/><stop offset="1" stop-color="#4f5c7a"/></linearGradient>');
const stars=Array.from({length:38},(_,i)=>{const x=28+(i*173)%940,y=14+(i*41)%132,r=i%5===0?1.8:1;return `<circle class="sky-star" cx="${x}" cy="${y}" r="${r}" fill="${i%3?'#f3e7d1':'#b7c9ff'}" style="--delay:-${i%7}s"/>`}).join('');
const town=Array.from({length:7},(_,i)=>{const x=90+i*112,y=165+(i%3)*9;return `<g transform="translate(${x} ${y})" opacity=".8"><rect x="-24" y="-39" width="48" height="40" rx="2" fill="${i%2?'#57597b':'#666084'}"/><path d="M-31-39 0-63 31-39" fill="#4a4c70"/><rect class="town-window" x="-14" y="-28" width="8" height="10" rx="1" fill="#f7cf99"/><rect class="town-window" x="6" y="-28" width="8" height="10" rx="1" fill="#f7cf99"/></g>`}).join('');
const flowers=Array.from({length:24},(_,i)=>{const x=30+(i*131)%945,y=341+(i*23)%67;return `<g class="luminous-flower" data-light-x="${x}" transform="translate(${x} ${y})"><path d="M0 0v10m0-4-5-3" stroke="#778e9a" stroke-width="1.4"/><g class="bloom"><circle r="4" fill="${i%3?'#f6d5bb':'#c9b4f6'}"/><circle r="1.4" fill="#fff4ce"/></g><circle class="bloom-halo" r="12" fill="url(#flowerPool)"/></g>`}).join('');
const lamps=(stage===5?[]:stage===2?[{x:160,y:300},{x:740,y:390},{x:950,y:300}]:stage===3?[{x:140,y:310},{x:680,y:320},{x:945,y:300}]:stage===4?[{x:180,y:310},{x:700,y:330},{x:945,y:300}]:[{x:182,y:292},{x:525,y:270},{x:714,y:283}]).map(({x,y})=>`<g class="town-lamp" data-light-x="${x}" transform="translate(${x} ${y})"><path d="M0 0v-76m-10 0h20m-8-18h16l4 18H-10z" fill="#55526e" stroke="#a397ae" stroke-width="2"/><ellipse class="lamp-halo" cx="0" cy="-83" rx="48" ry="55" fill="url(#warmPool)"/><path class="lamp-light" d="M-6-91H6l2 12H-8z" fill="#ffe1a2"/><ellipse class="lamp-ground" cy="5" rx="42" ry="12" fill="url(#warmPool)"/></g>`).join('');
return `<div class="scene storybook twilight ${worldAwake?'world-lit':''}"><svg viewBox="0 0 1000 420" aria-label="蓝紫暮光小镇，牵手可以点亮花朵与路灯"><defs>${defs}<linearGradient id="duskSky" x2="0" y2="1"><stop stop-color="#252541"/><stop offset=".5" stop-color="#74638d"/><stop offset="1" stop-color="#d495a6"/></linearGradient><radialGradient id="horizonGlow"><stop stop-color="#df9cb4" stop-opacity=".55"/><stop offset="1" stop-color="#d99bb3" stop-opacity="0"/></radialGradient><radialGradient id="warmPool"><stop stop-color="#ffe4a3" stop-opacity=".65"/><stop offset=".4" stop-color="#f5cfa1" stop-opacity=".2"/><stop offset="1" stop-color="#f5cfa1" stop-opacity="0"/></radialGradient><radialGradient id="flowerPool"><stop stop-color="#fce7c5" stop-opacity=".8"/><stop offset="1" stop-color="#edbaff" stop-opacity="0"/></radialGradient><linearGradient id="bridgeSpectrum"><stop stop-color="#afd9ff"/><stop offset=".5" stop-color="#e3c6f7"/><stop offset="1" stop-color="#fce0a7"/></linearGradient><linearGradient id="riverShine" x2="0" y2="1"><stop stop-color="#9cccf4" stop-opacity="0"/><stop offset=".5" stop-color="#d2b8ff" stop-opacity=".45"/><stop offset="1" stop-color="#eccb98" stop-opacity="0"/></linearGradient></defs><rect width="1000" height="420" fill="url(#duskSky)"/><ellipse cx="700" cy="130" rx="400" ry="160" fill="url(#horizonGlow)"/><g class="sky-stars">${stars}</g><circle cx="820" cy="66" r="45" fill="url(#warmPool)"/><path d="M832 40a25 25 0 1 0 13 39a21 21 0 0 1-13-39" fill="#f6dfbd"/><g class="clouds" fill="#c9accc" opacity=".18"><path d="M114 80q-12-15 5-20q5-20 25-10q21-9 24 12q20 9 1 18z"/><path d="M460 53q-14-13 4-18q10-22 27-7q23-6 24 12q17 13-5 13z"/></g><path d="M0 175Q150 50 330 144T670 131T1000 150V420H0" fill="#5b587f"/>${town}<path d="M0 230Q190 120 370 207T740 193T1000 205V420H0" fill="#475573"/><path d="M0 325Q180 223 365 272T730 272T1000 244V420H0" fill="#3d4e69"/><path d="M-30 390Q200 250 470 305T1040 275" fill="none" stroke="#62617d" stroke-width="72"/><path d="M-30 390Q200 250 470 305T1040 275" fill="none" stroke="#77708e" stroke-width="50" opacity=".55"/>${tree(80,205)}${tree(905,197,1.1)}${tree(790,155,.65)}${nightColors(extra)}${lamps}<g class="luminous-meadow">${stage===5?'':flowers}</g><g id="starFootprints" pointer-events="none"></g><g id="handAura" pointer-events="none" opacity="0"><ellipse cy="35" rx="72" ry="27" fill="url(#warmPool)"/><circle cy="22" r="16" fill="url(#flowerPool)"/></g><g id="worldRipple" pointer-events="none"></g>${people}<g id="riverConstellation" pointer-events="none" opacity="0"><path d="M430 40q55 120 14 360" fill="none" stroke="url(#riverShine)" stroke-width="57"/>${Array.from({length:12},(_,i)=>diamond(431+(i*19)%38,60+i*27,i%3===0?4:2.5,i%2?'#c4d9fc':'#f5d9ae')).join('')}</g><g pointer-events="none" fill="#52617d" opacity=".8"><path d="M0 420v-35q25 0 16 22q25-35 34-13q-4 20-19 26zm1000 0v-42q-23 0-19 23q-23-28-33-10q0 21 22 29z"/></g></svg><div id="overlay"></div></div>`;
};
function awakenWorld(x,y){if(worldAwake)return;worldAwake=true;const sc=document.querySelector('.scene');if(!sc)return;for(const el of sc.querySelectorAll('[data-light-x]'))el.style.setProperty('--light-delay',motionOff()?'0s':`${Math.abs(Number(el.dataset.lightX)-x)/450}s`);sc.classList.add('world-lit');document.body.classList.add('world-awake');const g=document.querySelector('#worldRipple');if(g&&!motionOff()){g.setAttribute('transform',`translate(${x} ${y+35})`);g.innerHTML='<circle r="1" fill="none" stroke="#f9d7ab" stroke-width="1.4" vector-effect="non-scaling-stroke"/>';const circle=g.firstElementChild;circle.animate({transform:['scale(1)','scale(700)'],opacity:[.8,0]},{duration:1800,easing:'ease-out'}).onfinish=()=>circle.remove()}if(stage===1)say('你看，牵住你的手以后，这座小镇就亮起来了。')}
const beforeDuskHandLine=handLine;
handLine=function(a,b){beforeDuskHandLine(a,b);const near=Math.abs(a.x-b.x)<76,active=handInHand&&near,mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2};if(active)awakenWorld(mid.x,mid.y);const aura=document.querySelector('#handAura');if(aura){aura.setAttribute('transform',`translate(${mid.x} ${mid.y})`);aura.style.opacity=active?'1':'0'}const svg=document.querySelector('.scene svg');if(svg!==lastDuskScene){lastDuskScene=svg;lastTrail=null}if(active&&svg&&lastTrail&&Math.hypot(lastTrail.x-mid.x,lastTrail.y-mid.y)>15&&!motionOff()){const g=document.querySelector('#starFootprints');if(g){while(g.childElementCount>=24)g.firstElementChild.remove();const p=document.createElementNS('http://www.w3.org/2000/svg','g');p.innerHTML=`<ellipse cx="${a.x}" cy="${a.y+43}" rx="5" ry="2.3" fill="#c7d8ff"/><ellipse cx="${b.x}" cy="${b.y+43}" rx="5" ry="2.3" fill="#f8d7b2"/>${diamond(mid.x,mid.y+39,3)}`;g.append(p);p.animate({opacity:[.9,0]},{duration:1900,easing:'ease-out'}).onfinish=()=>p.remove()}lastTrail=mid}else if(!lastTrail||!active)lastTrail=mid};
function updateDuskVisuals(){const sc=document.querySelector('.scene');if(!sc)return;sc.classList.toggle('world-lit',worldAwake);document.body.classList.toggle('world-awake',worldAwake);if(stage!==4)return;const bridgeEl=document.querySelector('#coopBridge');if(!bridgeEl)return;bridgeEl.style.opacity='1';const supported=coopPhase===0?holding.has('left'):holding.has('right');const blue=coopPhase>=1?15:Math.min(15,Math.ceil(coopAmount*15)+(supported?3:0)),gold=coopPhase>=2?15:coopPhase===1?Math.min(15,Math.ceil(coopAmount*15)+(supported?3:0)):0;for(const tile of bridgeEl.querySelectorAll('[data-tile]')){const i=Number(tile.dataset.tile);tile.classList.toggle('blue-on',i<blue);tile.classList.toggle('gold-on',i>=15-gold)}bridgeEl.classList.toggle('connected',coopPhase>=2);bridgeEl.classList.toggle('building',supported);bridgeEl.dataset.blue=String(blue);bridgeEl.dataset.gold=String(gold);const reflection=document.querySelector('#riverConstellation');if(reflection)reflection.style.opacity=coopPhase>=2?'1':'.15';if(coopPhase>=2)sc.classList.add('bridge-complete')}
const beforeDuskRender=render;
render=function(){beforeDuskRender();updateDuskVisuals();if(stage===0){document.querySelector('.eyebrow').textContent='A SMALL CHECK BEFORE THE STARS';document.querySelector('#hint').textContent='暮光小镇 · 建议平板横屏'}if(stage===1&&met&&!worldAwake)say('先牵一下手，好不好？这个小镇，还有一点光在等我们。');if(stage===4&&joined&&coopPhase===0)say('我按住这一侧的星光，你沿着亮起来的桥板先过去。');if(stage===4&&joined&&coopPhase===1)say('现在把光送回来接我吧。你在对岸，我就不怕。');if(stage===4&&joined&&coopPhase===2)say('你看，两边的光连起来了。原来我们一起，真的能点亮一条路。')};
const beforeDuskReset=reset;
reset=function(){worldAwake=false;lastTrail=null;lastDuskScene=null;document.body.classList.remove('world-awake');beforeDuskReset()};document.querySelector('#restart').onclick=reset;document.querySelector('#brand').onclick=e=>{e.preventDefault();reset()};
